[metadata] {"type": "create", "filePath": "/app/output/aider-leaderboard-poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Aider LLM Polyglot Coding Leaderboard 2025 - Infographic</title>
  <style>
    @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

    * { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --bg-primary: #060a14;
      --bg-secondary: #0c1221;
      --bg-card: #111827;
      --bg-card-hover: #1a2235;
      --border: #1e293b;
      --border-accent: #334155;
      --text-primary: #f1f5f9;
      --text-secondary: #94a3b8;
      --text-muted: #64748b;
      --accent-blue: #3b82f6;
      --accent-teal: #14b8a6;
      --accent-amber: #f59e0b;
      --openai: #10b981;
      --anthropic: #a78bfa;
      --google: #60a5fa;
      --deepseek: #fb923c;
    }

    body {
      background: var(--bg-primary);
      color: var(--text-primary);
      font-family: 'Inter', -apple-system, sans-serif;
      width: 1200px;
      height: 1800px;
      overflow: hidden;
    }

    .poster {
      width: 1200px;
      height: 1800px;
      padding: 48px 52px;
      position: relative;
      background: linear-gradient(175deg, #070b16 0%, #0a1020 30%, #0c1225 60%, #0a0e1a 100%);
    }

    /* Subtle grid background */
    .poster::before {
      content: '';
      position: absolute;
      inset: 0;
      background-image:
        linear-gradient(rgba(59,130,246,0.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(59,130,246,0.03) 1px, transparent 1px);
      background-size: 60px 60px;
      pointer-events: none;
    }

    /* Glow effects */
    .glow-top {
      position: absolute;
      top: -200px;
      left: 50%;
      transform: translateX(-50%);
      width: 800px;
      height: 500px;
      background: radial-gradient(ellipse, rgba(59,130,246,0.08) 0%, transparent 70%);
      pointer-events: none;
    }

    .glow-mid {
      position: absolute;
      top: 800px;
      right: -100px;
      width: 500px;
      height: 500px;
      background: radial-gradient(ellipse, rgba(167,139,250,0.05) 0%, transparent 70%);
      pointer-events: none;
    }

    /* HEADER */
    .header {
      position: relative;
      z-index: 1;
      margin-bottom: 28px;
    }

    .header-tag {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: rgba(59,130,246,0.12);
      border: 1px solid rgba(59,130,246,0.25);
      border-radius: 20px;
      padding: 5px 14px;
      font-size: 11px;
      font-weight: 600;
      color: var(--accent-blue);
      text-transform: uppercase;
      letter-spacing: 1.2px;
      margin-bottom: 14px;
    }

    .header-tag .dot {
      width: 6px; height: 6px;
      border-radius: 50%;
      background: var(--accent-blue);
      animation: pulse 2s infinite;
    }

    @keyframes pulse {
      0%, 100% { opacity: 1; }
      50% { opacity: 0.4; }
    }

    .header h1 {
      font-size: 42px;
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -1px;
      background: linear-gradient(135deg, #f1f5f9 30%, #94a3b8 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      margin-bottom: 8px;
    }

    .header .subtitle {
      font-size: 15px;
      color: var(--text-secondary);
      line-height: 1.5;
      max-width: 800px;
    }

    /* HERO METRICS */
    .hero-metrics {
      position: relative;
      z-index: 1;
      display: flex;
      gap: 16px;
      margin-bottom: 32px;
    }

    .metric-card {
      flex: 1;
      background: linear-gradient(135deg, rgba(17,24,39,0.9) 0%, rgba(17,24,39,0.6) 100%);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 18px 20px;
      position: relative;
      overflow: hidden;
    }

    .metric-card::before {
      content: '';
      position: absolute;
      top: 0; left: 0; right: 0;
      height: 2px;
    }

    .metric-card:nth-child(1)::before { background: linear-gradient(90deg, var(--accent-teal), transparent); }
    .metric-card:nth-child(2)::before { background: linear-gradient(90deg, var(--accent-blue), transparent); }
    .metric-card:nth-child(3)::before { background: linear-gradient(90deg, var(--accent-amber), transparent); }
    .metric-card:nth-child(4)::before { background: linear-gradient(90deg, #f43f5e, transparent); }
    .metric-card:nth-child(5)::before { background: linear-gradient(90deg, var(--openai), transparent); }
    .metric-card:nth-child(6)::before { background: linear-gradient(90deg, var(--anthropic), transparent); }

    .metric-value {
      font-family: 'JetBrains Mono', monospace;
      font-size: 28px;
      font-weight: 700;
      margin-bottom: 3px;
    }

    .metric-card:nth-child(1) .metric-value { color: var(--accent-teal); }
    .metric-card:nth-child(2) .metric-value { color: var(--accent-blue); }
    .metric-card:nth-child(3) .metric-value { color: var(--accent-amber); }
    .metric-card:nth-child(4) .metric-value { color: #f43f5e; }
    .metric-card:nth-child(5) .metric-value { color: var(--openai); }
    .metric-card:nth-child(6) .metric-value { color: var(--anthropic); }

    .metric-label {
      font-size: 10px;
      font-weight: 600;
      color: var(--text-muted);
      text-transform: uppercase;
      letter-spacing: 1px;
    }

    .metric-context {
      font-size: 10px;
      color: var(--text-muted);
      margin-top: 2px;
    }

    /* SECTION TITLES */
    .section-title {
      font-size: 16px;
      font-weight: 700;
      color: var(--text-primary);
      text-transform: uppercase;
      letter-spacing: 1.5px;
      margin-bottom: 16px;
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .section-title .icon {
      width: 28px; height: 28px;
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 14px;
    }

    .section-title .line {
      flex: 1;
      height: 1px;
      background: linear-gradient(90deg, var(--border-accent), transparent);
    }

    /* MODEL RANKING - Centerpiece */
    .ranking-section {
      position: relative;
      z-index: 1;
      margin-bottom: 28px;
    }

    .ranking-table {
      background: rgba(17,24,39,0.5);
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 20px 22px 18px;
    }

    .model-row {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 7px 0;
      position: relative;
    }

    .model-row:not(:last-child) {
      border-bottom: 1px solid rgba(30,41,59,0.5);
    }

    .model-rank {
      font-family: 'JetBrains Mono', monospace;
      font-size: 12px;
      font-weight: 600;
      color: var(--text-muted);
      width: 22px;
      text-align: center;
      flex-shrink: 0;
    }

    .model-row:nth-child(1) .model-rank,
    .model-row:nth-child(2) .model-rank,
    .model-row:nth-child(3) .model-rank {
      color: var(--accent-amber);
    }

    .model-family-dot {
      width: 8px; height: 8px;
      border-radius: 50%;
      flex-shrink: 0;
    }

    .dot-openai { background: var(--openai); box-shadow: 0 0 6px rgba(16,185,129,0.4); }
    .dot-anthropic { background: var(--anthropic); box-shadow: 0 0 6px rgba(167,139,250,0.4); }
    .dot-google { background: var(--google); box-shadow: 0 0 6px rgba(96,165,250,0.4); }
    .dot-deepseek { background: var(--deepseek); box-shadow: 0 0 6px rgba(251,146,60,0.4); }

    .model-name {
      font-size: 13px;
      font-weight: 600;
      color: var(--text-primary);
      width: 185px;
      flex-shrink: 0;
      white-space: nowrap;
    }

    .model-bar-container {
      flex: 1;
      height: 22px;
      background: rgba(30,41,59,0.3);
      border-radius: 4px;
      position: relative;
      overflow: hidden;
    }

    .model-bar {
      height: 100%;
      border-radius: 4px;
      position: relative;
      display: flex;
      align-items: center;
      justify-content: flex-end;
      padding-right: 8px;
      min-width: 40px;
    }

    .model-bar .bar-value {
      font-family: 'JetBrains Mono', monospace;
      font-size: 10px;
      font-weight: 600;
      color: rgba(255,255,255,0.9);
    }

    .bar-openai { background: linear-gradient(90deg, rgba(16,185,129,0.15), rgba(16,185,129,0.55)); }
    .bar-anthropic { background: linear-gradient(90deg, rgba(167,139,250,0.15), rgba(167,139,250,0.55)); }
    .bar-google { background: linear-gradient(90deg, rgba(96,165,250,0.15), rgba(96,165,250,0.55)); }
    .bar-deepseek { background: linear-gradient(90deg, rgba(251,146,60,0.15), rgba(251,146,60,0.55)); }

    .model-row:nth-child(1) .bar-openai,
    .model-row:nth-child(2) .bar-openai {
      background: linear-gradient(90deg, rgba(16,185,129,0.2), rgba(16,185,129,0.7));
    }

    .model-cost {
      font-family: 'JetBrains Mono', monospace;
      font-size: 11px;
      font-weight: 500;
      color: var(--text-muted);
      width: 55px;
      text-align: right;
      flex-shrink: 0;
    }

    .model-format-badge {
      font-size: 9px;
      font-weight: 600;
      padding: 2px 7px;
      border-radius: 4px;
      width: 70px;
      text-align: center;
      flex-shrink: 0;
    }

    .badge-diff {
      background: rgba(59,130,246,0.12);
      color: #93c5fd;
      border: 1px solid rgba(59,130,246,0.2);
    }

    .badge-diff-fenced {
      background: rgba(167,139,250,0.12);
      color: #c4b5fd;
      border: 1px solid rgba(167,139,250,0.2);
    }

    .model-compliance {
      font-family: 'JetBrains Mono', monospace;
      font-size: 11px;
      font-weight: 500;
      width: 40px;
      text-align: right;
      flex-shrink: 0;
      color: var(--text-secondary);
    }

    /* COST VS ACCURACY */
    .cost-accuracy-section {
      position: relative;
      z-index: 1;
      margin-bottom: 28px;
    }

    .cost-accuracy-container {
      background: rgba(17,24,39,0.5);
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 22px;
    }

    .scatter-chart {
      position: relative;
      width: 100%;
      height: 280px;
      margin-top: 8px;
    }

    .scatter-axes {
      position: absolute;
      bottom: 30px;
      left: 55px;
      right: 20px;
      top: 10px;
    }

    .scatter-x-axis {
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      height: 1px;
      background: var(--border-accent);
    }

    .scatter-y-axis {
      position: absolute;
      top: 0;
      left: 0;
      bottom: 0;
      width: 1px;
      background: var(--border-accent);
    }

    .scatter-grid-line {
      position: absolute;
      left: 0;
      right: 0;
      height: 1px;
      background: rgba(30,41,59,0.5);
    }

    .scatter-v-grid-line {
      position: absolute;
      top: 0;
      bottom: 0;
      width: 1px;
      background: rgba(30,41,59,0.5);
    }

    .scatter-point {
      position: absolute;
      width: 12px;
      height: 12px;
      border-radius: 50%;
      transform: translate(-50%, 50%);
      cursor: default;
      transition: transform 0.2s;
    }

    .scatter-point::after {
      content: attr(data-label);
      position: absolute;
      bottom: calc(100% + 4px);
      left: 50%;
      transform: translateX(-50%);
      font-size: 9px;
      font-weight: 600;
      color: var(--text-secondary);
      white-space: nowrap;
      opacity: 0;
      transition: opacity 0.2s;
      pointer-events: none;
    }

    .scatter-point:hover::after {
      opacity: 1;
    }

    .scatter-point.openai { background: var(--openai); box-shadow: 0 0 8px rgba(16,185,129,0.5); }
    .scatter-point.anthropic { background: var(--anthropic); box-shadow: 0 0 8px rgba(167,139,250,0.5); }
    .scatter-point.google { background: var(--google); box-shadow: 0 0 8px rgba(96,165,250,0.5); }
    .scatter-point.deepseek { background: var(--deepseek); box-shadow: 0 0 8px rgba(251,146,60,0.5); }

    .scatter-point.highlight {
      width: 16px;
      height: 16px;
    }

    .axis-label {
      position: absolute;
      font-size: 10px;
      font-weight: 500;
      color: var(--text-muted);
    }

    .x-axis-label {
      bottom: -22px;
      transform: translateX(-50%);
    }

    .y-axis-label {
      left: -45px;
      transform: translateY(50%);
    }

    .axis-title {
      font-size: 11px;
      font-weight: 600;
      color: var(--text-secondary);
      text-transform: uppercase;
      letter-spacing: 0.8px;
    }

    .x-axis-title {
      text-align: center;
      margin-top: 8px;
    }

    .y-axis-title {
      position: absolute;
      left: 0;
      top: 50%;
      transform: translateY(-50%) rotate(-90deg);
      transform-origin: center center;
      white-space: nowrap;
    }

    /* Value annotations */
    .value-callout {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: rgba(17,24,39,0.8);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 8px 14px;
      font-size: 11px;
    }

    .value-callout .vc-dot {
      width: 8px; height: 8px;
      border-radius: 50%;
    }

    .value-callout .vc-label {
      color: var(--text-secondary);
    }

    .value-callout .vc-value {
      font-family: 'JetBrains Mono', monospace;
      font-weight: 700;
      color: var(--text-primary);
    }

    .callouts-row {
      display: flex;
      gap: 12px;
      margin-top: 14px;
    }

    /* BOTTOM ROW */
    .bottom-row {
      position: relative;
      z-index: 1;
      display: flex;
      gap: 20px;
    }

    .edit-format-section,
    .takeaways-section {
      flex: 1;
    }

    .section-card {
      background: rgba(17,24,39,0.5);
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 20px 22px;
    }

    /* Edit format bars */
    .format-row {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 5px 0;
    }

    .format-name {
      font-size: 11px;
      font-weight: 600;
      color: var(--text-primary);
      width: 145px;
      flex-shrink: 0;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .format-bar-bg {
      flex: 1;
      height: 16px;
      background: rgba(30,41,59,0.3);
      border-radius: 3px;
      overflow: hidden;
    }

    .format-bar {
      height: 100%;
      border-radius: 3px;
      display: flex;
      align-items: center;
      justify-content: flex-end;
      padding-right: 6px;
    }

    .format-bar .fb-value {
      font-family: 'JetBrains Mono', monospace;
      font-size: 9px;
      font-weight: 600;
      color: rgba(255,255,255,0.85);
    }

    .fb-openai { background: linear-gradient(90deg, rgba(16,185,129,0.1), rgba(16,185,129,0.45)); }
    .fb-anthropic { background: linear-gradient(90deg, rgba(167,139,250,0.1), rgba(167,139,250,0.45)); }
    .fb-google { background: linear-gradient(90deg, rgba(96,165,250,0.1), rgba(96,165,250,0.45)); }
    .fb-deepseek { background: linear-gradient(90deg, rgba(251,146,60,0.1), rgba(251,146,60,0.45)); }

    /* Key Takeaways */
    .takeaway-item {
      display: flex;
      align-items: flex-start;
      gap: 10px;
      padding: 8px 0;
    }

    .takeaway-item:not(:last-child) {
      border-bottom: 1px solid rgba(30,41,59,0.4);
    }

    .takeaway-icon {
      width: 24px;
      height: 24px;
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      font-size: 12px;
      font-weight: 700;
    }

