      { name: 'o4-mini (high)', acc: 71.1, cost: 4.47, family: 'openai' },
    ];

    const scatterEl = document.getElementById('scatter-chart');
    const axesEl = scatterEl.querySelector('.scatter-axes') || scatterEl;

    // Chart bounds
    const chartLeft = 55;
    const chartRight = scatterEl.offsetWidth || 1060;
    const chartTop = 10;
    const chartBottom = 250;
    const chartWidth = chartRight - chartLeft - 35;
    const chartHeight = chartBottom - chartTop;

    const costMin = 0, costMax = 32;
    const accMin = 68, accMax = 92;

    function mapX(cost) { return chartLeft + ((cost - costMin) / (costMax - costMin)) * chartWidth; }
    function mapY(acc) { return chartBottom - ((acc - accMin) / (accMax - accMin)) * chartHeight; }

    // Build scatter HTML
    let scatterHTML = '';

    // Y-axis gridlines
    for (let a = 70; a <= 90; a += 5) {
      const y = mapY(a);
      scatterHTML += `<div class="scatter-grid-line" style="bottom:${chartBottom - y + 30}px;left:${chartLeft}px;right:20px;"></div>`;
      scatterHTML += `<div class="axis-label y-axis-label" style="bottom:${chartBottom - y + 30 - 5}px;">${a}%</div>`;
    }

    // X-axis gridlines
    for (let c = 5; c <= 30; c += 5) {
      const x = mapX(c);
      scatterHTML += `<div class="scatter-v-grid-line" style="left:${x}px;top:${chartTop}px;bottom:${30}px;"></div>`;
      scatterHTML += `<div class="axis-label x-axis-label" style="left:${x}px;">$${c}</div>`;
    }

    // Axes
    scatterHTML += `<div class="scatter-x-axis" style="left:${chartLeft}px;right:20px;bottom:30px;"></div>`;
    scatterHTML += `<div class="scatter-y-axis" style="left:${chartLeft}px;top:${chartTop}px;bottom:30px;"></div>`;

    // Value frontier line (connect best value models)
