      { name: 'o4-mini (high)', val: 87.2, family: 'openai' },
      { name: 'GPT-5 (low)', val: 85.8, family: 'openai' },
    ];

    const formatBarsEl = document.getElementById('format-bars');
    let formatHTML = '';

    formatModels.forEach(m => {
      const widthPct = ((m.val - 82) / 16) * 100;
      formatHTML += `
        <div class="format-row">
