const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({
    viewport: { width: 1200, height: 1800 },
    deviceScaleFactor: 2,
  });

  const htmlPath = path.resolve(__dirname, 'aider-leaderboard-poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle', timeout: 30000 });

  // Wait for fonts and infographic to render
  await page.waitForTimeout(3000);

  // Ensure all content is rendered
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(2000);

  // Take full-page screenshot
  await page.screenshot({
    path: path.resolve(__dirname, 'final_poster.png'),
    fullPage: false,
    clip: { x: 0, y: 0, width: 1200, height: 1800 },
  });

  console.log('Poster rendered successfully!');
  await browser.close();
})();

