from PIL import Image
img = Image.open('/app/output/final_poster.png')

# Find where content actually ends (last row with significant bright pixels)
for y in range(500, 3600, 50):
    bright = 0
    for x in range(0, 2400, 15):
        px = img.getpixel((x, y))
        if max(px) > 80:
            bright += 1
    if bright > 5:
        last_y = y
print(f'Last row with content: y={last_y}')

# Find where content starts
for y in range(0, 500, 20):
    bright = 0
    for x in range(0, 2400, 15):
        px = img.getpixel((x, y))
        if max(px) > 80:
            bright += 1
    if bright > 5:
        first_y = y
        break
print(f'First row with content: y={first_y}')

# Check what's visible
for y in range(0, 3600, 100):
    bright = 0
    for x in range(0, 2400, 15):
        px = img.getpixel((x, y))
        if max(px) > 80:
            bright += 1
    if bright > 3:
        print(f'  y={y}: {bright} bright pixels')
"

